Item.method_code:
interface FormItemInPackage extends FormItem {
	packageName: string;
};

interface FormWithCustomControlInPackage extends FormItemInPackage {
	controlId: string;
	controlPackageName: string;
}

const processUpdateResult = async (updateResponse: {
	statuses: string[] | { type: string, message: string }[] ;
}): Promise<void> => {
	if (updateResponse.statuses?.[0] === 'NotModified') {
		const successMessage = getResource('item_methods.no_update_needed');
		notify(successMessage, {
			type: 'success'
		});
		return;
	}

	const failedItems = updateResponse.statuses.filter(
		(status: { type: string; message: string } | string) =>
			typeof status === 'object' && status.type === 'Error'
	) as { message: string }[];

	if (failedItems.length === 0) {
		const successMessage = getResource('item_methods.package_updated');
		notify(successMessage, {
			type: 'success'
		});
		return;
	}

	const errorMessage = failedItems.map(({ message }) => message).join('\r\n');
	if (errorMessage !== '') {
		await alert(errorMessage, { type: 'error' });
	}
};

const instructUserToUseAddAction = async (
		items: { name: string }[]
		) => {
	const newLine = '\r\n';
	const errorMessages = items.map(({name}) => getResource('item_methods.package_with_form_id_does_not_exists', name, itemTypeName))
		.join(newLine);

	if (errorMessages.length !== 0) {
		await alert(`${errorMessages}${newLine}${getResource(
			'item_methods.use_add_package_action_message'
		)}`);
	}
}

const formIds = formItems.map((item) => item.id);
const response: { formsNotInPackage: FormItem[]; formsWithNoPermissionsToUpdate: FormItemInPackage[]; formsToUpdate: FormItemInPackage[]; formsWithCustomPartUpdate: FormWithCustomControlInPackage[] } = await odataFetch('method.FilterFormItemsBeforePackUpdate', {
	method: 'POST',
	body: JSON.stringify({
		ids: formIds.toString()
	})
});

if (response.formsNotInPackage.length === formIds.length) {
	await alert(getResource('item_methods.package_with_form_does_not_exists'));
	return;
}

if (response.formsNotInPackage.length > 0) {
	await instructUserToUseAddAction(response.formsNotInPackage);
}

if (response.formsWithNoPermissionsToUpdate.length > 0)
{
	await instructUserToUseAddAction(response.formsWithNoPermissionsToUpdate);
}

for (const { id, name, packageName } of response.formsToUpdate)
{
	const confirmResult = await confirm(
		getResource(
			'item_methods.package_definition_update_confirmation',
			name,
			packageName
		)
	);

	if (confirmResult !== 'ok') {
		continue;
	}

	const updateResponse = await odataFetch('method.UpdateItemInPackageDefinition', {
		method: 'POST',
		body: JSON.stringify({
			packageName,
			Relationships: { Item:  { id: id, itemTypeName}}
		})
	});

	await processUpdateResult(updateResponse);
}

for (const { id, controlId, controlPackageName, name } of response.formsWithCustomPartUpdate)
{
	const confirmResult = await confirm(
		getResource(
			'item_methods.package_definition_update_confirmation',
			name,
			controlPackageName
		)
	);

	if (confirmResult !== 'ok') {
		continue;
	}

	const partialUpdateResponse = await odataFetch('method.UpdateItemInPackageDefinition', {
		method: 'POST',
		body: JSON.stringify({
			packageName: controlPackageName,
			partialUpdate: '1',
			Relationships: { Item:  { id: id, controlId: controlId, itemTypeName } }
		})
	});

	await processUpdateResult(partialUpdateResponse);
}
